const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080";

export type AdminDashboardStats = {
  pendingKyc: number;
  openQueries: number;
  activeDisputes: number;
  pendingResolutions: number;
};

export type KycStatus =
  | "NOT_STARTED"
  | "PENDING"
  | "UNDER_REVIEW"
  | "APPROVED"
  | "REJECTED";

export type AdminKycApplication = {
  id: string;
  userId: string;
  email: string;
  firstName: string;
  lastName: string;
  status: KycStatus;
  documentType: string | null;
  documentNumberMasked: string | null;
  submittedAt: string | null;
  updatedAt: string | null;
};

export type KycDecisionRequest = {
  decision: "APPROVED" | "REJECTED";
  reason?: string;
};

export type ClientQuery = {
  id: string;
  userId: string;
  subject: string;
  category: string;
  status: string;
  priority: string;
  description: string;
  resolution: string | null;
  assignedAdminId: string | null;
  createdAt: string;
  updatedAt: string;
  resolvedAt: string | null;
};

/*
 * ============================================================
 * ADMIN USERS
 * ============================================================
 */

export type AdminUser = {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  status: "ACTIVE" | "INACTIVE";
  emailVerified: boolean;
  createdAt: string;
};

export type AdminUserStatus = "ACTIVE" | "INACTIVE";

/*
 * ============================================================
 * AUTHENTICATION
 * ============================================================
 */

function getToken() {
  if (typeof window === "undefined") {
    return null;
  }

  return (
    localStorage.getItem("oakpay.admin.accessToken") ||
    localStorage.getItem("oakpay.accessToken")
  );
}

/*
 * ============================================================
 * GENERIC API REQUEST
 * ============================================================
 */

async function request<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const token = getToken();

  const headers = new Headers(options.headers);

  headers.set("Content-Type", "application/json");

  if (token) {
    headers.set("Authorization", `Bearer ${token}`);
  }

  const response = await fetch(`${API_BASE_URL}${path}`, {
    ...options,
    headers,
  });

  /*
   * Authentication / authorisation failure.
   */
  if (response.status === 401 || response.status === 403) {
    throw new Error("ADMIN_AUTH_REQUIRED");
  }

  /*
   * Other API errors.
   */
  if (!response.ok) {
    const body = await response.text();

    throw new Error(
      body || `Request failed with status ${response.status}`,
    );
  }

  /*
   * No content.
   */
  if (response.status === 204) {
    return undefined as T;
  }

  return response.json();
}

/*
 * ============================================================
 * ADMIN API
 * ============================================================
 */

export const adminApi = {
  /*
   * ==========================================================
   * DASHBOARD
   * ==========================================================
   */

  dashboard() {
    return request<AdminDashboardStats>(
      "/api/v1/admin/dashboard",
    );
  },

  /*
   * ==========================================================
   * KYC MANAGEMENT
   * ==========================================================
   */

  kyc: {
    list(status?: KycStatus) {
      const query = status
        ? `?status=${encodeURIComponent(status)}`
        : "";

      return request<AdminKycApplication[]>(
        `/api/v1/admin/kyc${query}`,
      );
    },

    get(id: string) {
      return request<AdminKycApplication>(
        `/api/v1/admin/kyc/${id}`,
      );
    },

    decide(
      id: string,
      data: KycDecisionRequest,
    ) {
      return request<AdminKycApplication>(
        `/api/v1/admin/kyc/${id}/decision`,
        {
          method: "POST",
          body: JSON.stringify(data),
        },
      );
    },
  },

  /*
   * ==========================================================
   * CLIENT QUERIES
   * ==========================================================
   */

  queries: {
    list(status?: string) {
      const query = status
        ? `?status=${encodeURIComponent(status)}`
        : "";

      return request<ClientQuery[]>(
        `/api/v1/admin/queries${query}`,
      );
    },

    get(id: string) {
      return request<ClientQuery>(
        `/api/v1/admin/queries/${id}`,
      );
    },

    assign(
      id: string,
      adminUserId: string,
    ) {
      return request<ClientQuery>(
        `/api/v1/admin/queries/${id}/assign`,
        {
          method: "POST",
          body: JSON.stringify({
            adminUserId,
          }),
        },
      );
    },

    resolve(
      id: string,
      resolution: string,
    ) {
      return request<ClientQuery>(
        `/api/v1/admin/queries/${id}/resolve`,
        {
          method: "POST",
          body: JSON.stringify({
            resolution,
          }),
        },
      );
    },
  },

  /*
   * ==========================================================
   * USERS & ACCESS
   * ==========================================================
   */

  users: {
    /*
     * Get users.
     *
     * Examples:
     *
     * adminApi.users.list()
     * adminApi.users.list("ACTIVE")
     * adminApi.users.list("INACTIVE")
     * adminApi.users.list(undefined, "CLIENT")
     */
    list(
      status?: AdminUserStatus,
      role?: string,
    ) {
      const params = new URLSearchParams();

      if (status) {
        params.set("status", status);
      }

      if (role) {
        params.set("role", role);
      }

      const query = params.toString();

      return request<AdminUser[]>(
        `/api/v1/admin/users${
          query ? `?${query}` : ""
        }`,
      );
    },

    /*
     * Get one user.
     */
    get(id: string) {
      return request<AdminUser>(
        `/api/v1/admin/users/${id}`,
      );
    },

    /*
     * Activate or deactivate a user.
     */
    updateStatus(
      id: string,
      status: AdminUserStatus,
    ) {
      return request<AdminUser>(
        `/api/v1/admin/users/${id}/status`,
        {
          method: "PATCH",
          body: JSON.stringify({
            status,
          }),
        },
      );
    },
  },
};